def get_mac_vendor(mac: str) -> str:
    """根据 MAC 地址获取厂商名称"""
    if not mac:
        return ""
    mac = mac.lower().replace("-", ":")
    if len(mac) < 8:
        return ""
    oui = mac[:8]
    return MAC_OUI_VENDORS.get(oui, "")
